import {field,number as num,select as sel,text,e,bytes,result,error,download,registerResource,linkDownload} from '../ui.mjs';
import {uploadHTML,bindUpload,parsePages,canvas,canvasBlob} from '../media.mjs';
import {loadScript} from '../extras.mjs';
import {need,fileResult,textFile} from './shared.mjs';
import {zipStore} from './plus-core.mjs';
let engine;
async function pdfEngine(){if(!engine)engine=import('../assets/vendor/pdfjs/pdf.min.mjs').then(pdfjs=>{pdfjs.GlobalWorkerOptions.workerSrc=new URL('../assets/vendor/pdfjs/pdf.worker.min.mjs',import.meta.url).href;return pdfjs;});return engine;}
const pdfOptions=()=>{const base=new URL('../assets/vendor/pdfjs/',import.meta.url);return {cMapUrl:new URL('cmaps/',base).href,cMapPacked:true,standardFontDataUrl:new URL('standard_fonts/',base).href,wasmUrl:new URL('wasm/',base).href,iccUrl:new URL('iccs/',base).href,enableXfa:false,stopAtErrors:true,maxImageSize:24000000,canvasMaxAreaInBytes:32000000};};
export function setupDocsPlus(tool,mount,out){const id=tool.id,compress=id==='pdf-compressor',extract=id==='pdf-to-text';let file,doc,task,disposed=false,busy=false,release=()=>{},sequence=0;const fields=compress?[sel('mode','Compression method',[['rewrite','Structure rewrite · no page rasterization'],['raster','Image-based copy · removes selectable text / interactive features']],'rewrite'),num('dpi','Raster resolution (DPI)',120,72,300,1),num('quality','JPEG quality (%)',65,30,95,1)]:[text('pages','Page numbers / ranges','1'),...(extract?[]:[sel('format','Image format',[['image/jpeg','JPEG'],['image/png','PNG']],'image/jpeg'),num('dpi','Resolution (DPI)',150,72,300,1),num('quality','JPEG quality (%)',90,30,100,1)])];mount.innerHTML='<h2>'+({ 'pdf-to-images':'A page, ready to share.','pdf-to-text':'Find the words already in your PDF.','pdf-compressor':'A lighter copy, with the tradeoffs in view.'}[id])+'</h2>'+uploadHTML('.pdf,application/pdf',false,'Choose a PDF','PDF · up to 30 MB · no password-protected files')+'<p class="form-note" data-pdf-state role="status">Choose a PDF to begin.</p><form><div class="form-grid">'+fields.map(field).join('')+'</div><div class="form-actions"><button class="btn primary" type="submit" disabled>'+({ 'pdf-to-images':'Export page images','pdf-to-text':'Extract text','pdf-compressor':'Create PDF copy'}[id])+'</button><button type="button" class="btn secondary" data-change-pdf>Change PDF</button></div><div class="form-error"></div><p class="form-note" data-work-progress role="status"></p></form><p class="form-note">'+(compress?'Keep the original. Rewriting changes the file and can invalidate digital signatures. Image-based copies also remove selectable text, links, forms and annotations. A file can become larger.':extract?'Existing text layers only. Scanned page images need OCR, and reading order can vary.':'Images contain pixels rather than a searchable text layer. Large pages are capped at eight million rendered pixels; inspect the actual exported dimensions.')+'</p>';const f=mount.querySelector('form'),button=f.querySelector('[type=submit]'),input=mount.querySelector('input[type=file]'),state=mount.querySelector('[data-pdf-state]'),progress=mount.querySelector('[data-work-progress]'),err=f.querySelector('.form-error');mount.querySelector('[data-change-pdf]').onclick=()=>{input.value='';input.click();};
 bindUpload(mount,async files=>{if(busy)return;const candidate=files[0];if(!candidate)return;const token=++sequence;input.disabled=true;button.disabled=true;err.innerHTML='';state.textContent='Reading PDF locally…';try{need(candidate.size<=30*1024*1024,'Use a PDF no larger than 30 MB.');if(task)await task.destroy();const pdfjs=await pdfEngine();if(disposed||token!==sequence)return;let password=false;task=pdfjs.getDocument({data:new Uint8Array(await candidate.arrayBuffer()),...pdfOptions()});task.onPassword=()=>{password=true;task.destroy();};let loaded;try{loaded=await task.promise;}catch(ex){throw Error(password?'This PDF requires a password. Choose an unprotected copy you are authorized to process.':ex.message||'Could not read this PDF.');}if(disposed||token!==sequence)return;need(loaded.numPages<=1000,'Use a PDF with no more than 1,000 pages.');doc=loaded;file=candidate;if(!compress)f.elements.pages.value=doc.numPages===1?'1':'1-'+Math.min(extract?10:3,doc.numPages);state.textContent=file.name+' · '+doc.numPages+' pages · '+bytes(file.size)+' · ready';button.disabled=false;release();out.innerHTML='<div class="result-placeholder">PDF added. Choose your options, then create the result.</div>';}catch(ex){if(!disposed){state.textContent='The PDF could not be opened. Choose another file.';error(err,ex.message);doc=null;file=null;}}finally{if(!disposed)input.disabled=false;}});
 async function renderPage(index,dpi){const page=await doc.getPage(index+1),base=page.getViewport({scale:1}),scale=Math.min(dpi/72,Math.sqrt(8000000/(base.width*base.height))),viewport=page.getViewport({scale}),c=canvas(Math.ceil(viewport.width),Math.ceil(viewport.height));try{await page.render({canvas:c,canvasContext:c.getContext('2d'),viewport,background:'#ffffff'}).promise;return {c,width:base.width,height:base.height};}catch(ex){c.width=c.height=0;throw ex;}finally{page.cleanup();}}
 f.onsubmit=async ev=>{ev.preventDefault();if(!doc||busy||!f.reportValidity())return;busy=true;button.disabled=input.disabled=true;mount.querySelector('[data-change-pdf]').disabled=true;err.innerHTML='';const token=sequence;try{const v=Object.fromEntries(new FormData(f));if(extract){const selected=parsePages(v.pages,doc.numPages);need(selected.length<=100,'Extract up to 100 pages per operation.');const parts=[];let textCharacters=0;for(let i=0;i<selected.length;i++){progress.textContent='Reading text · '+(i+1)+' / '+selected.length;const page=await doc.getPage(selected[i]+1),content=await page.getTextContent();let text='';for(const item of content.items)if(typeof item.str==='string')text+=item.str+(item.hasEOL?'\n':' ');textCharacters+=text.length;need(textCharacters<=5000000,'Extracted text exceeds five million characters. Choose a smaller page range.');parts.push('--- Page '+(selected[i]+1)+' ---\n'+text.trim());page.cleanup();if(disposed||token!==sequence)return;}const text=parts.join('\n\n');textFile(out,text,'nepocore-pdf-text.txt');if(!parts.some(p=>p.replace(/--- Page \d+ ---/,'').trim()))out.insertAdjacentHTML('afterbegin','<p class="form-note">No embedded text was found. This PDF may contain scanned images. OCR is a separate operation.</p>');}
 else if(!compress){const selected=parsePages(v.pages,doc.numPages);need(selected.length<=30,'Export up to 30 pages at a time.');const output=[];let total=0;for(let i=0;i<selected.length;i++){progress.textContent='Rendering page '+(selected[i]+1)+' · '+(i+1)+' / '+selected.length;const {c}=await renderPage(selected[i],+v.dpi),blob=await canvasBlob(c,v.format,+v.quality/100);output.push({blob,width:c.width,height:c.height,name:'page-'+String(selected[i]+1).padStart(4,'0')+(v.format==='image/png'?'.png':'.jpg')});c.width=c.height=0;total+=blob.size;need(total<=100*1024*1024,'Rendered output exceeds 100 MB. Use fewer pages or lower resolution.');if(disposed||token!==sequence)return;}release();if(output.length===1)release=fileResult(out,output[0].blob,output[0].name,{image:true,details:[['Dimensions',output[0].width+' × '+output[0].height+' px']]});else{const zipped=zipStore(await Promise.all(output.map(async x=>[x.name,new Uint8Array(await x.blob.arrayBuffer())])));release=fileResult(out,zipped,'nepocore-pdf-images.zip',{details:[['Images',output.length],['Image bytes before ZIP',bytes(total)]]});const gallery=document.createElement('div');gallery.className='pdf-image-gallery';for(const item of output.slice(0,4)){const card=document.createElement('div'),url=URL.createObjectURL(item.blob);registerResource(out,()=>URL.revokeObjectURL(url));card.innerHTML='<img alt="'+e(item.name)+'"><small>'+e(item.name)+' · '+item.width+' × '+item.height+'</small><button class="btn secondary small">Download image</button>';card.querySelector('img').src=url;registerResource(out,linkDownload(card.querySelector('button'),item.blob,item.name));gallery.append(card);}out.prepend(gallery);}}
 else{const {PDFDocument}=await loadScript('./assets/vendor/pdf-lib.min.js','PDFLib');let bytesOut;if(v.mode==='rewrite'){progress.textContent='Rewriting PDF structure…';const copy=await PDFDocument.load(await file.arrayBuffer(),{updateMetadata:false});bytesOut=await copy.save({useObjectStreams:true,addDefaultPage:false});}else{need(doc.numPages<=40,'Image-based compression supports up to 40 pages. Split a larger document first.');const copy=await PDFDocument.create();for(let i=0;i<doc.numPages;i++){progress.textContent='Rendering copy · '+(i+1)+' / '+doc.numPages;const {c,width,height}=await renderPage(i,+v.dpi),jpeg=await canvasBlob(c,'image/jpeg',+v.quality/100),img=await copy.embedJpg(await jpeg.arrayBuffer()),page=copy.addPage([width,height]);page.drawImage(img,{x:0,y:0,width,height});c.width=c.height=0;if(disposed||token!==sequence)return;}bytesOut=await copy.save();}if(disposed||token!==sequence)return;const blob=new Blob([bytesOut],{type:'application/pdf'}),difference=1-blob.size/file.size;release();release=fileResult(out,blob,'nepocore-pdf-copy.pdf',{details:[['Input',bytes(file.size)],['Output',bytes(blob.size)],['Size change',difference>=0?(difference*100).toFixed(1)+'% smaller':(-difference*100).toFixed(1)+'% larger'],['Method',v.mode==='raster'?'Image-based pages':'Structure rewrite']]});out.insertAdjacentHTML('beforeend','<p class="form-note">'+(difference<0?'This copy is larger. Keep the original if size is your only goal. ':'')+(v.mode==='raster'?'The new PDF has image-based pages; text layers, forms, links and annotations are not preserved.':'The page content is not intentionally rasterized, but file rewriting changes bytes and can invalidate signatures.')+'</p>');const original=document.createElement('button');original.className='btn secondary small';original.textContent='Download original';out.querySelector('.result-actions').append(original);linkDownload(original,file,file.name);}
 progress.textContent='Complete. No PDF content was uploaded.';
 }catch(ex){if(!disposed)error(err,ex.message||'Could not finish this PDF operation.');}finally{if(!disposed){busy=false;button.disabled=!doc;input.disabled=false;mount.querySelector('[data-change-pdf]').disabled=false;}}};return()=>{disposed=true;sequence++;release();task?.destroy();doc=null;file=null;};}
